SELECT sku_id,sku_code, warehouse_id, physical_stock, reserved_stock, version, updated_at
FROM sku_stock
WHERE sku_id = #{skuId}

SELECT sku_id,sku_code, warehouse_id, physical_stock, reserved_stock, version, updated_at
FROM sku_stock
WHERE sku_id = #{skuId} AND warehouse_id = #{warehouseId}

SELECT sku_id,sku_code, warehouse_id, physical_stock, reserved_stock, version, updated_at
FROM sku_stock
WHERE sku_code = #{skuCode} AND warehouse_id = #{warehouseId}

mapper.update:
UPDATE sku_stock
SET
    physical_stock = physical_stock - #{quantity},
    version = version + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE sku_id = #{skuId}
  AND warehouse_id = #{warehouseId}
  AND physical_stock >= #{quantity}

UPDATE sku_stock
SET reserved_stock = reserved_stock - #{quantity},
    version = version + 1,
    updated_at = NOW()
WHERE sku_id = #{skuId}
  AND warehouse_id = #{warehouseId}
  AND reserved_stock >= #{quantity}
